{
  "tasks": [
    {
      "task_id": "T1",
      "title": "一组与三组团队响应分钟中位数升序排名",
      "business_question": "计算一组和三组团队的响应分钟中位数，并按中位数升序排列。约束：只看一组与三组；指标为响应分钟中位数；排序方式为升序。",
      "priority": "P0",
      "priority_reason": "直接回答核心分析目标“按团队计算一组与三组的响应分钟中位数，并升序排名”，支持比较不同团队响应速度的决策。删除此任务将无法获得核心指标及排名结果。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "in",
                "value": [
                  "一组",
                  "三组"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0005",
                "alias": "median_response_minutes"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "median_response_minutes",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
